"""Make the central plan describe the actual delivered executions, preserving capture options."""
from pathlib import Path
import json,re,shutil,importlib.util

ROOT=Path(__file__).resolve().parents[1]
PLAN=ROOT/'planning';PLAN.mkdir(exist_ok=True)
def clean(value):
    if isinstance(value,str):
        value=re.sub(r'\\u([0-9a-fA-F]{4})',lambda m:chr(int(m.group(1),16)),value)
        return value.replace('\\n','\n')
    if isinstance(value,list):return[clean(x)for x in value]
    if isinstance(value,dict):return{k:clean(v)for k,v in value.items()}
    return value
for name in ['campaigns.json','copybook.md','strategy.md']:
    src=ROOT/name;dst=PLAN/('capture-'+name)
    if not dst.exists():shutil.copy2(src,dst)
j=clean(json.loads((PLAN/'capture-campaigns.json').read_text()))
(PLAN/'capture-campaigns.json').write_text(json.dumps(j,ensure_ascii=False,indent=2))
for name in ['capture-copybook.md','capture-strategy.md']:
    path=PLAN/name;path.write_text(clean(path.read_text()))
