lines=['# LOOKSi / current campaign copybook','','These are the current delivered executions. Optional founder performances and longer continuous demonstrations are separate production versions in planning/capture-campaigns.json. No posts have been published.','']
for c in j['campaigns']:
    lines +=[f"## {c['id']} / {c['title']}",'',f"**Voice:** {c['voice']}  \n**Execution:** {c['preferred_execution']}  \n**Hero duration:** {c['video']['duration']} seconds",'', '### Instagram caption','',c['instagram']['caption'],'','### Reddit title','',c['reddit']['title'],'','### Reddit post','',c['reddit']['body'],'','### Image alt text','',c['hero_image']['alt_text'],'','### Current assets','']
